#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# shellcheck disable=SC2046
# generate-build-metadata.sh — Write build-metadata.json (GAV + RAML coordinates) from the built JAR and source pom.xml.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/steps/build-mule-application.yml
#   step   : "Generate Build Metadata" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
# The shellcheck codes disabled above come from constructs inherited verbatim from that source.
#
# Outputs: GROUP_ID (output), ARTIFACT_ID (output), VERSION (output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

# >>> extracted body
echo "[DEBUG] ============================================"
echo "[DEBUG] BUILD METADATA GENERATION"
echo "[DEBUG] ============================================"
echo "[DEBUG] Working directory: $(ci_default_working_directory)"
echo "[DEBUG] Searching for pom.properties in target/..."

# Extract GAV from pom.properties inside the built JAR
POM_PROPS=$(find $(ci_default_working_directory)/target -name "pom.properties" -path "*/META-INF/maven/*" | head -1)

if [[ -z "$POM_PROPS" ]]; then
  echo "[DEBUG] pom.properties NOT FOUND. Listing target dir:"
  echo "[DEBUG] $(find $(ci_default_working_directory)/target -type f -name "*.properties" | head -10)"
  ci_log_error "pom.properties not found in target directory."
  exit 1
fi
echo "[DEBUG] Found pom.properties at: $POM_PROPS"
echo "[DEBUG] pom.properties content:"
echo "[DEBUG] $(cat "$POM_PROPS")"

GROUP_ID=$(grep "^groupId=" "$POM_PROPS" | cut -d'=' -f2)
ARTIFACT_ID=$(grep "^artifactId=" "$POM_PROPS" | cut -d'=' -f2)
VERSION=$(grep "^version=" "$POM_PROPS" | cut -d'=' -f2)

echo "Build Metadata: ${GROUP_ID}:${ARTIFACT_ID}:${VERSION}"
echo "[DEBUG] Parsed GAV: groupId=$GROUP_ID, artifactId=$ARTIFACT_ID, version=$VERSION"

# Extract RAML dependency coordinates from source pom.xml (namespace-agnostic)
SOURCE_POM="$(ci_default_working_directory)/pom.xml"
RAML_GROUP_ID=""
RAML_ARTIFACT_ID=""
RAML_VERSION=""
if [[ -f "$SOURCE_POM" ]]; then
  RAML_BLOCK=$(awk '/<dependency>/{block=""} {block=block $0 "\n"} /<\/dependency>/{if (block ~ /<classifier>raml<\/classifier>/) print block}' "$SOURCE_POM")
  if [[ -n "$RAML_BLOCK" ]]; then
    RAML_GROUP_ID=$(echo "$RAML_BLOCK" | grep '<groupId>' | sed 's/.*<groupId>\(.*\)<\/groupId>.*/\1/' | tr -d '[:space:]')
    RAML_ARTIFACT_ID=$(echo "$RAML_BLOCK" | grep '<artifactId>' | sed 's/.*<artifactId>\(.*\)<\/artifactId>.*/\1/' | tr -d '[:space:]')
    RAML_VERSION=$(echo "$RAML_BLOCK" | grep '<version>' | sed 's/.*<version>\(.*\)<\/version>.*/\1/' | tr -d '[:space:]')
    echo "[DEBUG] RAML dependency found in source pom.xml: ${RAML_GROUP_ID}:${RAML_ARTIFACT_ID}:${RAML_VERSION}"
  else
    echo "[DEBUG] No RAML dependency (classifier=raml) in source pom.xml"
  fi
fi

# Generate metadata JSON
METADATA_DIR="$(ci_artifact_staging_dir)/build-metadata"
mkdir -p "$METADATA_DIR"

cat > "$METADATA_DIR/build-metadata.json" <<EOF
{
  "groupId": "$GROUP_ID",
  "artifactId": "$ARTIFACT_ID",
  "version": "$VERSION",
  "classifier": "mule-application",
  "ramlGroupId": "$RAML_GROUP_ID",
  "ramlArtifactId": "$RAML_ARTIFACT_ID",
  "ramlVersion": "$RAML_VERSION",
  "buildNumber": "$(ci_build_number)",
  "sourceBranch": "$(ci_source_branch)",
  "commitId": "$(ci_commit_sha)"
}
EOF
echo "[DEBUG] Build metadata JSON written to: $METADATA_DIR/build-metadata.json"
echo "[DEBUG] $(cat "$METADATA_DIR/build-metadata.json")"

ci_set_var GROUP_ID "$GROUP_ID"
ci_set_var ARTIFACT_ID "$ARTIFACT_ID"
ci_set_var VERSION "$VERSION"
echo "[DEBUG] Output variables set: GROUP_ID=$GROUP_ID, ARTIFACT_ID=$ARTIFACT_ID, VERSION=$VERSION"
echo "[DEBUG] BUILD METADATA GENERATION COMPLETE"
# <<< extracted body
